const cat = JSON.parse($('AI Agent').first().json.output).categoria;
const now = new Date();
const month = now.getMonth() + 1;
const year = now.getFullYear();
const monthNames = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const mesNombre = monthNames[month - 1];
const mon = { Jan:1, Feb:2, Mar:3, Apr:4, May:5, Jun:6, Jul:7, Aug:8, Sep:9, Oct:10, Nov:11, Dec:12 };

function parseDate(f) {
  const s = String(f || '').trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m && m[1] !== 'YYYY') return { y: +m[1], m: +m[2], d: +m[3] };
  m = s.match(/([A-Za-z]{3}) (\d{1,2}), (\d{4})/);
  if (m) return { y: +m[3], m: mon[m[1]], d: +m[2] };
  return null;
}

const rows = $input.all().map(i => i.json).filter(r => r.Fecha && r.Monto !== undefined && r.Monto !== '');
const lines = [];
let ingresos = 0;
let gastos = 0;
for (const r of rows) {
  const d = parseDate(r.Fecha);
  if (!d || d.y !== year || d.m !== month) continue;
  const monto = Number(String(r.Monto).replace(/[^0-9.-]/g, ''));
  if (isNaN(monto)) continue;
  if (monto >= 0) ingresos += monto; else gastos += monto;
  const dd = String(d.d).padStart(2, '0') + '/' + String(d.m).padStart(2, '0');
  lines.push(dd + '  ' + (monto >= 0 ? '+' : '-') + '$' + Math.abs(monto));
}

let text;
if (lines.length === 0) {
  text = '📊 Resumen de ' + cat + ' (' + mesNombre + ' ' + year + ')\nNo hay movimientos este mes.';
} else {
  text = '📊 Resumen de ' + cat + ' (' + mesNombre + ' ' + year + ')\n' + lines.join('\n') + '\n\n⬆️ Ingresos: $' + ingresos + '\n⬇️ Gastos: $' + Math.abs(gastos) + '\n🧮 Balance del mes: $' + (ingresos + gastos);
}
return [{ json: { contexto: 'ACCION: RESUMIR\nMensaje del usuario: ' + $('Telegram Trigger').first().json.message.text + '\n' + text } }];

const raw = String($input.first().json.output || '').replace(/```json|```/g, '').trim();
const valid = ['Renta','Servicios','Limpieza','Personal','Escuela','Regalos','Ahorro','Mascotas','Otro'];
let items = [];
try { items = JSON.parse(raw).items || []; } catch (e) { items = []; }
const out = items
  .map(i => ({ categoria: valid.includes(i.categoria) ? i.categoria : 'Otro', monto: Number(i.monto) }))
  .filter(i => !isNaN(i.monto) && i.monto > 0);
if (out.length === 0) {
  return [{ json: { vacio: true } }];
}
return out.map(i => ({ json: i }));

const cats = $('Lista categorías').all().map(i => i.json.categoria);
const rows = $input.all().map(i => i.json);
const lineas = cats.map((c, idx) => {
  const r = rows[idx] || {};
  const t = r.Total;
  const ok = t !== undefined && t !== '' && !isNaN(Number(String(t).replace(/[^0-9.-]/g, '')));
  return c + ': ' + (ok ? Number(String(t).replace(/[^0-9.-]/g, '')) : 'sin datos');
});
return [{ json: { contexto: 'ACCION: RESUMEN_GENERAL\nMensaje del usuario: ' + $('Telegram Trigger').first().json.message.text + '\nSaldo disponible actual en cada apartado según el Excel:\n' + lineas.join('\n') } }];
